# /etc/nginx/nginx.conf — main context
user www-data;
worker_processes auto;
pid /run/nginx.pid;

events {
    worker_connections 1024;
    multi_accept on;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    sendfile on;
    tcp_nopush on;
    keepalive_timeout 65;

    gzip on;
    gzip_min_length 1024;
    gzip_types text/css application/javascript application/json image/svg+xml;

    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}

# Plain HTTP: redirect everything to the canonical https host
server {
    listen 80;
    listen [::]:80;
    server_name example.com www.example.com;

    return 301 https://example.com$request_uri;
}

server {
    listen 443 ssl;
    http2 on;
    server_name example.com;

    ssl_certificate     /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;

    root /var/www/example;
    index index.html;
}

# First block for a listen address is the default; be explicit about it
server {
    listen 80 default_server;
    server_name _;

    # Drops requests whose Host header matches no real site
    return 444;
}

# test.example.com serves the same app from a different root
server {
    listen 80;
    server_name test.example.com;
    root /var/www/example-test;
}

server {
    listen 80;
    server_name static.example.com;

    root /var/www/cheatrs/dist;
    index index.html;

    location / {
        # File, then directory, then 404; no directory listing
        try_files $uri $uri/ =404;
    }

    location /assets/ {
        # Fingerprinted files never change, so cache them for a year
        expires 1y;
        add_header Cache-Control "public, immutable";
    }
}

location / {
    # Single-page app: unknown paths return index.html, not 404
    try_files $uri /index.html;
}

# Never serve dotfiles such as .env or .git
location ~ /\. {
    deny all;
    access_log off;
}

# Serve pre-compressed files when the client accepts them
location ~* \.(css|js)$ {
    gzip_static on;
    expires 7d;
}

location /api/ {
    # Trailing slash strips /api/ before the request reaches the app
    proxy_pass http://127.0.0.1:8080/;

    proxy_http_version 1.1;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;

    proxy_connect_timeout 5s;
    proxy_read_timeout 60s;
    proxy_send_timeout 60s;
}

# WebSockets need the upgrade headers and a long read timeout
location /ws {
    proxy_pass http://127.0.0.1:3000;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
    proxy_read_timeout 3600s;
}

location /upload {
    # Stream the body to the app instead of buffering it on disk
    proxy_request_buffering off;
    client_max_body_size 512m;
    proxy_pass http://127.0.0.1:8080;
}

location /api/ {
    proxy_buffering on;
    proxy_buffers 16 16k;
    proxy_busy_buffers_size 32k;
    proxy_pass http://127.0.0.1:8080;
}

# add_header is inherited only if the child block declares none of its own
add_header X-Content-Type-Options "nosniff" always;
add_header X-Frame-Options "SAMEORIGIN" always;
add_header Referrer-Policy "strict-origin-when-cross-origin" always;
add_header Content-Security-Policy "default-src 'self'; img-src 'self' data:" always;

# HSTS only after every subdomain works over https
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

location /api/ {
    # CORS for one trusted origin, with the preflight answered by nginx
    add_header Access-Control-Allow-Origin "https://app.example.com" always;
    add_header Access-Control-Allow-Methods "GET, POST, OPTIONS" always;
    add_header Access-Control-Allow-Headers "Authorization, Content-Type" always;

    if ($request_method = OPTIONS) {
        return 204;
    }

    # Strip the header the upstream sets before adding our own
    proxy_hide_header X-Powered-By;
    proxy_pass http://127.0.0.1:8080;
}

# Limit the request body per location, and per virtual host
client_max_body_size 8m;
client_body_timeout 12s;
client_header_timeout 12s;

location /files/ {
    client_max_body_size 256m;
}

server {
    listen 443 ssl;
    http2 on;
    server_name example.com;

    ssl_certificate     /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;

    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    ssl_prefer_server_ciphers off;

    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;

    ssl_stapling on;
    ssl_stapling_verify on;
}

# 1. Exact match, highest priority
location = /health {
    access_log off;
    return 200 "ok\n";
}

# 2. Prefix with ^~ stops regex evaluation
location ^~ /static/ {
    root /var/www;
}

# 3. Case-sensitive regex, first match in file order wins
location ~ \.php$ {
    include snippets/fastcgi-php.conf;
    fastcgi_pass unix:/run/php/php8.3-fpm.sock;
}

# 4. Plain prefix, longest match wins, regexes still get a chance
location / {
    try_files $uri $uri/ =404;
}

# Named location used as an error fallback
location /api/ {
    proxy_pass http://127.0.0.1:8080;
    error_page 502 503 504 = @maintenance;
}

location @maintenance {
    default_type text/html;
    return 503 "<h1>Back in a minute</h1>";
}

# Nested location narrows the parent prefix
location /app/ {
    location ~* \.(png|jpg|svg)$ {
        expires 30d;
    }
}

# return is cheaper than rewrite for a plain redirect
location /old-blog/ {
    return 301 /blog/;
}

# Capture groups carry the slug into the new path
rewrite ^/post/([0-9]+)$ /articles/$1 permanent;

# break rewrites and keeps the request in this block
location /app/ {
    rewrite ^/app/(.*)$ /$1 break;
    proxy_pass http://127.0.0.1:3000;
}

# Canonical host: www to apex, keeping the path and query
server {
    listen 80;
    server_name www.example.com;
    return 301 https://example.com$request_uri;
}

# Force the trailing slash for a directory-style URL
location = /docs {
    return 301 /docs/;
}

upstream backend {
    # Fewest active connections; round-robin is the default
    least_conn;
    server 10.0.0.11:8080 max_fails=3 fail_timeout=10s;
    server 10.0.0.12:8080 max_fails=3 fail_timeout=10s;
    server 10.0.0.13:8080 backup;

    # Reuse upstream connections instead of opening one per request
    keepalive 32;
}

server {
    location / {
        proxy_pass http://backend;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
    }
}

# Sticky by client address instead of by cookie
upstream app {
    ip_hash;
    server 10.0.0.21:3000;
    server 10.0.0.22:3000;
}

# Weighted split, useful while draining an old box
upstream canary {
    server 10.0.0.31:3000 weight=9;
    server 10.0.0.32:3000 weight=1;
}

# levels and keys_zone size the on-disk cache; inactive evicts unused entries
proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=api_cache:10m
                 max_size=1g inactive=60m use_temp_path=off;

server {
    location /api/public/ {
        proxy_cache api_cache;
        proxy_cache_key "$scheme$request_method$host$request_uri";
        proxy_cache_valid 200 5m;
        proxy_cache_valid 404 1m;
        proxy_cache_use_stale error timeout updating http_502 http_503 http_504;
        proxy_cache_background_update on;
        add_header X-Cache-Status $upstream_cache_status;
        proxy_pass http://127.0.0.1:8080;
    }
}

# One second of cache absorbs bursts without serving stale data for long
proxy_cache_path /var/cache/nginx/micro levels=1:2 keys_zone=micro:10m max_size=256m inactive=10m;

location / {
    proxy_cache micro;
    proxy_cache_valid 200 1s;
    # A single request fills the cache; the rest wait for it
    proxy_cache_lock on;
    proxy_cache_lock_timeout 5s;
    # Never cache a request that carries a session cookie
    proxy_no_cache $cookie_session;
    proxy_pass http://127.0.0.1:3000;
}

# Custom format with upstream timings; request_time is in seconds
log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                '$status $body_bytes_sent "$http_referer" "$http_user_agent" '
                'rt=$request_time uct=$upstream_connect_time urt=$upstream_response_time';

access_log /var/log/nginx/access.log main buffer=32k flush=5s;
error_log  /var/log/nginx/error.log warn;

# 502: the upstream refused the connection (wrong port, app down, SELinux)
# 504: it accepted but answered late, so raise proxy_read_timeout
location /api/ {
    proxy_pass http://127.0.0.1:8080;
    proxy_connect_timeout 5s;
    proxy_read_timeout 120s;
    proxy_next_upstream error timeout http_502;
    proxy_intercept_errors on;
    error_page 502 504 /50x.html;
}

location = /50x.html {
    root /usr/share/nginx/html;
}
